mapper.select:
SELECT COUNT(*)
FROM pass_record
WHERE company_name NOT IN ('物业', '保安', '供应商', '访客', '访客专用策略')

    AND person_name LIKE concat(#{name},'%')


    AND company_name LIKE concat(#{department},'%')


    AND DATE_FORMAT(pass_time,'%H:%i:%s') >= #{smallTime}


    AND DATE_FORMAT(pass_time,'%H:%i:%s') <= #{bigTime}


    AND DATE_FORMAT(pass_time,'%Y-%m-%d') >= #{smallDate}


    AND DATE_FORMAT(pass_time,'%Y-%m-%d') <= #{bigDate}

SELECT person_name `name`, company_name department, device_name deviceName, pass_time passTime
FROM pass_record
WHERE company_name NOT IN ('物业', '保安', '供应商', '访客', '访客专用策略')

    AND person_name LIKE concat(#{name},'%')


    AND company_name LIKE concat(#{department},'%')


    AND DATE_FORMAT(pass_time,'%H:%i:%s') >= #{smallTime}


    AND DATE_FORMAT(pass_time,'%H:%i:%s') <= #{bigTime}


    AND DATE_FORMAT(pass_time,'%Y-%m-%d') >= #{smallDate}


    AND DATE_FORMAT(pass_time,'%Y-%m-%d') <= #{bigDate}

ORDER BY pass_time DESC, id

    limit #{page}, #{row}
